// === Tab: mySketch ===
// Definitely not a grid #genuary18 #genuary!
// created by Henriqe Silva, 2022-01-18
// https://openprocessing.org/sketch/1799648

    'use strict'
    let l1, l2, l3, l4
    let d = 7
    let d1 = 7
    let m = 200
    let t = 0
    let a = 0.5

    function setup() {
      createCanvas(800, 800);
      background(255)
      stroke(0)
      l1 = new linep(d)
      l1.move(m, m, m, height - m)
      l1.sh()
      l2 = new linep(d)
      l2.move(width - m, m, width - m, height - m)
      l2.sh()


      l3 = new linep(d1)
      l3.move(m, m, width - m, m)
      l3.sh()
      l4 = new linep(d1)
      l4.move(m, height - m, width - m, height - m)
      l4.sh()

      for (let i = 0; i <= d; i++) line(l1.pts[i].x, l1.pts[i].y, l2.pts[i].x, l2.pts[i].y)
      for (let i = 0; i <= d1; i++) line(l3.pts[i].x, l3.pts[i].y, l4.pts[i].x, l4.pts[i].y)
    }

    function draw() {

      background(255)
      l1.move(l1.pts[0].x + sin(noise(t + 15) * 2 * PI) * a, l1.pts[0].y + sin(noise(t + 25) * 2 * PI) * a, l1.pts[1].x + sin(noise(t + 35) * 2 * PI) * a, l1.pts[1].y + sin(noise(t + 45) * 2 * PI) * a)
      l1.sh()
      l2.move(l2.pts[0].x + sin(noise(t + 55) * 2 * PI) * a, l2.pts[0].y + sin(noise(t + 55) * 2 * PI) * a, l2.pts[1].x + sin(noise(t + 65) * 2 * PI) * a, l2.pts[1].y + sin(noise(t + 75) * 2 * PI) * a)
      l2.sh()
      for (let i = 0; i <= d; i++) line(l1.pts[i].x, l1.pts[i].y, l2.pts[i].x, l2.pts[i].y)
      l3.move(l3.pts[0].x + sin(noise(t + 15) * 2 * PI) * a, l3.pts[0].y + sin(noise(t + 25) * 2 * PI) * a, l3.pts[1].x + sin(noise(t + 35) * 2 * PI) * a, l3.pts[1].y + sin(noise(t + 45) * 2 * PI) * a)
      l3.sh()
      l4.move(l4.pts[0].x + sin(noise(t + 15) * 2 * PI) * a, l4.pts[0].y + sin(noise(t + 25) * 2 * PI) * a, l2.pts[1].x + sin(noise(t + 65) * 2 * PI) * a, l2.pts[1].y + sin(noise(t + 75) * 2 * PI) * a)
      l4.sh()
      for (let i = 0; i <= d1; i++) line(l3.pts[i].x, l3.pts[i].y, l4.pts[i].x, l4.pts[i].y)

      t += 0.01;

    }


    function linep(d) {

      this.d = d
      this.pts = []

      this.move = function(x1, y1, x2, y2) {
        let dx = x2 - x1
        let dy = y2 - y1
        let intx = dx / this.d
        let inty = dy / this.d
        this.pts = []
        this.pts.push(createVector(x1, y1))
        this.pts.push(createVector(x2, y2))

        for (let i = 1; i < d; i++) {
          let x = x1 + intx * i
          let y = y1 + inty * i
          this.pts.push(createVector(x, y))
        }
      }


      this.sh = function() {
        line(this.pts[0].x, this.pts[0].y, this.pts[1].x, this.pts[1].y)

      }

    }
